export interface QuizQuestion {
  id: string;
  enonce: string;
  choix: string[];
  reponse: number; // index dans choix
  explication: string;
}

export interface Quiz {
  slug: string;
  titre: string;
  questions: QuizQuestion[];
}

export interface SonExercice {
  motReference: string; // mot que l'enfant écoute en premier (porte le son cible)
  propositions: string[]; // mots parmi lesquels choisir
  reponse: number; // index dans propositions du mot qui a le même son que motReference
}

export interface IntonationExercice {
  phrase: string; // phrase à écouter dans la langue de la leçon
  type: "question" | "affirmation" | "exclamation";
}

export interface FriseEvenement {
  date: string; // ex: "1789", "Ve siècle", "1515-1547"
  titre: string; // court intitulé de l'événement
  description?: string;
  important?: boolean; // met en avant un moment charnière sur la frise
}

export interface Lesson {
  slug: string;
  titre: string;
  matiere: string; // slug matière
  niveau: string; // slug niveau
  duree: string; // "15 min"
  resume: string;
  objectifs: string[];
  contenu: string[]; // paragraphes / sections en texte (rendu simple)
  quiz: Quiz;
  motsAEcouter?: string[]; // mots-exemples à écouter (utilisé pour les sons du CP)
  alphabet?: { lettre: string; nomEtranger: string }[]; // liste des lettres pour les leçons d'alphabet en langue étrangère : nomEtranger = lu dans la langue du cours, lettre = relue en français
  sonsAIdentifier?: SonExercice[]; // exercice "clique sur le mot qui a le même son"
  ecouteIntonation?: IntonationExercice[]; // écoute active : reconnaître question / affirmation / exclamation
  histoire?: { titre: string; texte: string }; // petite histoire à écouter, utilisant le vocabulaire de la leçon (remplace ecouteIntonation pour les langues étrangères)
  exercicesSupplementaires?: QuizQuestion[]; // mini-exercices pratiques distincts du quiz principal (même forme qu'une question de quiz), avec correction immédiate, affichés dans une section « Exercices supplémentaires » séparée
  phrasesLectureCp?: string[]; // phrases faciles à lire (CP) : les lettres muettes finales sont marquées entre tildes, ex. "Le cha~t~ dor~t~.", pour être affichées dans une couleur différente à l'écran
  friseChronologique?: FriseEvenement[]; // frise chronologique (leçons d'histoire)
  illustration?: string; // schéma SVG inline (viewBox 0 0 320 200) pour illustrer la leçon
  photo?: { url: string; alt: string; credit: string }; // photo/portrait d'archive libre de droits (Wikimedia Commons), avec crédit
  galerie?: { url: string; alt: string; credit: string }[]; // galerie de plusieurs photos/illustrations d'archive, avec crédit pour chacune
  contenuImages?: { apresParagraphe: number; url: string; alt: string; credit: string; centre?: boolean }[]; // image inline dans le contenu : apresParagraphe = index du paragraphe après lequel afficher (0 = après le 1er, -1 = avant tous, en intro)
  vocabulaire?: { mot: string; definition: string }[]; // lexique : mots ou expressions de vocabulaire/dictionnaire à connaître pour une oeuvre littéraire
  resumeLecture?: boolean; // affiche un encadré où l'élève peut rédiger son propre résumé de lecture (oeuvres étudiées en classe)
  contenuLangueSeule?: number[]; // indices (0-based) des paragraphes de `contenu` à lire intégralement dans la langue de la leçon (sans découpage français/langue étrangère) — utile pour une simple liste de lettres/mots dans la langue cible
  audioSon?: { url: string; label: string }[]; // clip(s) audio enregistré(s) par une vraie voix (pas de synthèse vocale) pour le(s) son(s) cible(s) d'une leçon de phonétique CP/CE1 ; url pointe vers un fichier dans /public/audio/sons/, absent si non encore fourni — le composant SonReel masque chaque bouton dont le fichier n'existe pas
  audioLecon?: string; // fichier audio d'une vraie voix enregistrée (pas de synthèse vocale) lisant la leçon entière ; branché sur le bouton "Écouter toute la leçon" existant, url dans /public/audio/lecons/, retombe automatiquement sur la synthèse vocale si le fichier est absent
  audioParagraphes?: string[]; // un fichier audio par paragraphe de `contenu` (même ordre, même longueur) ; branché sur le petit bouton "Écouter" de chaque paragraphe, retombe sur la synthèse vocale si l'entrée est absente pour ce paragraphe
}

