export function lessonBySlug(slug: string) {
  return LESSONS.find((l) => l.slug === slug);
}

export function lessonsByMatiere(matiere: string) {
  return LESSONS.filter((l) => l.matiere === matiere);
}

export function lessonsByNiveau(niveau: string) {
  return LESSONS.filter((l) => l.niveau === niveau);
}

export function lessonByNiveauMatiere(niveau: string, matiere: string) {
  return LESSONS.find((l) => l.niveau === niveau && l.matiere === matiere);
}
